    //
    // Note:    The filter frequency is based on the sample frequency o
    //          is the operating frequency of the digital closed loop. 
    //          that a compensated value has to be programmed if anothe
    //          frequency is used in the coherent voltage sampling mode
    //
    double filter_programmed = 10.0 kHz * 1 MHz / sample_frequ;
