    //
    // AWG = Force pin
    //
    rdi.dc().pin("avi_REGIN")
            .vForceRange(3.0 V).vForce(0.0 V)
            .iClamp(-50 mA, 50 mA).iForceRange(50 mA)
            .execute();
    RDI_BEGIN();
    {
        rdi.port("port_REGIN").dc().pin("avi_REGIN")
                .vForce()
