rdi.dc("id").pin().vForce().vMeas().waveform(wav).FS(10 KHz).execute();
rdi.dc("id").pin().iForce().iMeas().waveform(wav).samplePeriod(100 us).
rdi.dc("id").pin().iForce().vMeas().waveform(wav).sampleCycle(1000).exe
